/* Pixel-themed palette: dark slate, off-white, teal, coral, amber */
:root {
  --bg: #1e1e2f;
  --card: #2d2d44;
  --text: #f0f0f0;
  --accent: #4ecdc4;
  --accent-dark: #3aa89f;
  --danger: #ff6b6b;
  --warning: #ffd93d;
  --border: #555;
  --shadow: #111;
  --radius: 0px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
  padding: 1rem;
  background-image: linear-gradient(45deg, #1a1a2e 25%, transparent 25%),
                    linear-gradient(-45deg, #1a1a2e 25%, transparent 25%),
                    linear-gradient(45deg, transparent 75%, #1a1a2e 75%),
                    linear-gradient(-45deg, transparent 75%, #1a1a2e 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--shadow);
  padding: 1.5rem;
  width: 100%;
  max-width: 640px;
  margin: 2rem 0;
}

h1, h2 {
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 0.5rem;
}

h1 {
  font-size: 1.75rem;
  color: var(--accent);
  text-align: center;
}

h2 {
  font-size: 1.25rem;
  margin-top: 1.5rem;
  padding-bottom: 0.25rem;
  border-bottom: 4px solid var(--border);
}

.subtitle {
  text-align: center;
  color: #aaa;
  margin-bottom: 1.5rem;
}

.form-row {
  margin-bottom: 1rem;
}

label {
  display: block;
  margin-bottom: 0.25rem;
  font-weight: 600;
  color: var(--accent);
}

select, input {
  width: 100%;
  padding: 0.75rem;
  background: #1e1e2f;
  border: 3px solid var(--border);
  color: var(--text);
  font-family: inherit;
  font-size: 1rem;
  outline: none;
}

select:focus, input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-dark);
}

.btn {
  display: inline-block;
  padding: 0.75rem 1.5rem;
  border: 3px solid var(--border);
  background: var(--accent);
  color: #1e1e2f;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  cursor: pointer;
  transition: transform 0.1s, box-shadow 0.1s;
  box-shadow: 4px 4px 0 var(--shadow);
}

.btn:hover {
  background: var(--accent-dark);
  transform: translate(-1px, -1px);
  box-shadow: 5px 5px 0 var(--shadow);
}

.btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 var(--shadow);
}

.btn:focus-visible {
  outline: 3px solid var(--warning);
  outline-offset: 2px;
}

.btn.danger {
  background: var(--danger);
  color: #fff;
  padding: 0.25rem 0.75rem;
  font-size: 0.875rem;
}

.error {
  color: var(--danger);
  margin-top: 0.5rem;
  font-weight: 600;
  min-height: 1.5em;
}

.expense-list, .settle-list {
  list-style: none;
  margin-top: 0.5rem;
}

.expense-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem;
  background: #1e1e2f;
  border: 3px solid var(--border);
  margin-bottom: 0.5rem;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.expense-item .info {
  flex: 1 1 auto;
  font-size: 1rem;
}

.expense-item .amount {
  font-weight: 700;
  color: var(--accent);
}

.empty-message {
  color: #aaa;
  font-style: italic;
  margin-top: 0.5rem;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 0.75rem;
  margin-top: 0.5rem;
}

.summary-card {
  background: #1e1e2f;
  border: 3px solid var(--border);
  padding: 0.75rem;
  text-align: center;
}

.summary-card .name {
  font-weight: 700;
  color: var(--accent);
  text-transform: uppercase;
  font-size: 0.875rem;
}

.summary-card .paid {
  font-size: 1.25rem;
  font-weight: 700;
  margin: 0.25rem 0;
}

.summary-card .balance {
  font-size: 0.875rem;
  font-weight: 600;
}

.balance.positive {
  color: var(--accent);
}

.balance.negative {
  color: var(--danger);
}

.settle-item {
  padding: 0.75rem;
  background: #1e1e2f;
  border: 3px solid var(--border);
  margin-bottom: 0.5rem;
  font-weight: 600;
}

.settle-item .arrow {
  color: var(--warning);
  margin: 0 0.5rem;
}

@media (max-width: 480px) {
  .card {
    padding: 1rem;
  }
  h1 {
    font-size: 1.5rem;
  }
  .expense-item {
    flex-direction: column;
    align-items: flex-start;
  }
  .summary-grid {
    grid-template-columns: 1fr;
  }
}

// Pixel Expense Splitter
(function() {
  'use strict';

  const FRIENDS = ['Alice', 'Bob', 'Charlie'];
  let expenses = []; // { id, payer, amount (in cents) }
  let nextId = 1;

  // DOM elements
  const form = document.getElementById('expense-form');
  const payerSelect = document.getElementById('payer');
  const amountInput = document.getElementById('amount');
  const formError = document.getElementById('form-error');
  const expenseList = document.getElementById('expense-list');
  const emptyMessage = document.getElementById('empty-message');
  const summaryDiv = document.getElementById('summary');
  const settleList = document.getElementById('settle-list');
  const settleEmpty = document.getElementById('settle-empty');

  // Helpers
  function formatCents(cents) {
    return '$' + (cents / 100).toFixed(2);
  }

  function parseAmountToCents(value) {
    const num = parseFloat(value);
    if (isNaN(num) || num <= 0) return null;
    return Math.round(num * 100);
  }

  // Render functions
  function renderExpenses() {
    expenseList.innerHTML = '';
    if (expenses.length === 0) {
      emptyMessage.style.display = 'block';
      return;
    }
    emptyMessage.style.display = 'none';
    expenses.forEach(exp => {
      const li = document.createElement('li');
      li.className = 'expense-item';
      li.dataset.id = exp.id;

      const info = document.createElement('span');
      info.className = 'info';
      info.textContent = exp.payer + ' paid ';

      const amountSpan = document.createElement('span');
      amountSpan.className = 'amount';
      amountSpan.textContent = formatCents(exp.amount);
      info.appendChild(amountSpan);

      const removeBtn = document.createElement('button');
      removeBtn.type = 'button';
      removeBtn.className = 'btn danger';
      removeBtn.textContent = 'Remove';
      removeBtn.setAttribute('aria-label', 'Remove expense: ' + exp.payer + ' paid ' + formatCents(exp.amount));
      removeBtn.addEventListener('click', () => removeExpense(exp.id));

      li.appendChild(info);
      li.appendChild(removeBtn);
      expenseList.appendChild(li);
    });
  }

  function renderSummary() {
    const totalCents = expenses.reduce((sum, e) => sum + e.amount, 0);
    const shareCents = Math.floor(totalCents / FRIENDS.length);
    // Distribute remainder cents to first friends? Actually we need each person's fair share as total/3.
    // For balances, we use exact division: each person's fair share = total / 3 (in cents, may have fraction).
    // We'll compute balances as (paid - total/3) using floating point for display, but for settle-up we'll use integer cents with remainder handling.

    const paid = {};
    FRIENDS.forEach(f => paid[f] = 0);
    expenses.forEach(e => { paid[e.payer] += e.amount; });

    // Compute balances in cents (paid - share), share = total/3. We'll keep as float for display but settle using integer cents.
    const total = totalCents;
    const share = total / FRIENDS.length;
    const balances = {};
    FRIENDS.forEach(f => {
      balances[f] = paid[f] - share;
    });

    summaryDiv.innerHTML = '';
    FRIENDS.forEach(f => {
      const card = document.createElement('div');
      card.className = 'summary-card';

      const nameEl = document.createElement('div');
      nameEl.className = 'name';
      nameEl.textContent = f;

      const paidEl = document.createElement('div');
      paidEl.className = 'paid';
      paidEl.textContent = formatCents(paid[f]);

      const balEl = document.createElement('div');
      balEl.className = 'balance ' + (balances[f] >= 0 ? 'positive' : 'negative');
      const balAbs = Math.abs(balances[f]);
      const balStr = formatCents(Math.round(balAbs * 100) / 100); // round to cents for display
      if (Math.abs(balances[f]) < 0.01) {
        balEl.textContent = 'Settled';
      } else if (balances[f] > 0) {
        balEl.textContent = 'is owed ' + balStr;
      } else {
        balEl.textContent = 'owes ' + balStr;
      }

      card.appendChild(nameEl);
      card.appendChild(paidEl);
      card.appendChild(balEl);
      summaryDiv.appendChild(card);
    });
  }

  function renderSettleUp() {
    // Compute minimal transactions using integer cents with remainder distribution.
    const totalCents = expenses.reduce((sum, e) => sum + e.amount, 0);
    const n = FRIENDS.length;
    const baseShare = Math.floor(totalCents / n);
    const remainder = totalCents % n;

    // Each friend's fair share: first 'remainder' friends get baseShare+1, others baseShare.
    // But to be fair, we should distribute remainder to those who paid more? Actually we need balances such that sum of balances = 0.
    // We'll compute each person's balance: paid - fairShare (where fairShare is integer cents).
    const paid = {};
    FRIENDS.forEach(f => paid[f] = 0);
    expenses.forEach(e => { paid[e.payer] += e.amount; });

    // Assign fair shares: we want sum of fairShares = totalCents. We can assign baseShare to all, then distribute remainder cents to friends in order.
    const fairShares = {};
    FRIENDS.forEach((f, i) => {
      fairShares[f] = baseShare + (i < remainder ? 1 : 0);
    });

    const balances = {};
    FRIENDS.forEach(f => {
      balances[f] = paid[f] - fairShares[f];
    });

    // Now settle: separate debtors (negative balance) and creditors (positive balance).
    const debtors = [];
    const creditors = [];
    FRIENDS.forEach(f => {
      if (balances[f] < 0) debtors.push({ name: f, amount: -balances[f] });
      else if (balances[f] > 0) creditors.push({ name: f, amount: balances[f] });
    });

    // Sort by amount descending for efficiency (optional)
    debtors.sort((a, b) => b.amount - a.amount);
    creditors.sort((a, b) => b.amount - a.amount);

    const transactions = [];
    let i = 0, j = 0;
    while (i < debtors.length && j < creditors.length) {
      const debtor = debtors[i];
      const creditor = creditors[j];
      const amount = Math.min(debtor.amount, creditor.amount);
      if (amount > 0) {
        transactions.push({ from: debtor.name, to: creditor.name, amount: amount });
      }
      debtor.amount -= amount;
      creditor.amount -= amount;
      if (debtor.amount === 0) i++;
      if (creditor.amount === 0) j++;
    }

    settleList.innerHTML = '';
    if (transactions.length === 0) {
      settleEmpty.style.display = 'block';
      return;
    }
    settleEmpty.style.display = 'none';
    transactions.forEach(t => {
      const li = document.createElement('li');
      li.className = 'settle-item';
      li.innerHTML = t.from + ' <span class="arrow">→</span> ' + t.to + ': ' + formatCents(t.amount);
      settleList.appendChild(li);
    });
  }

  function updateAll() {
    renderExpenses();
    renderSummary();
    renderSettleUp();
  }

  // Event handlers
  function addExpense(e) {
    e.preventDefault();
    formError.textContent = '';
    const payer = payerSelect.value;
    const amountCents = parseAmountToCents(amountInput.value);

    if (!payer || !FRIENDS.includes(payer)) {
      formError.textContent = 'Please select a payer.';
      return;
    }
    if (amountCents === null || amountCents <= 0) {
      formError.textContent = 'Please enter a valid positive amount.';
      amountInput.focus();
      return;
    }

    expenses.push({ id: nextId++, payer, amount: amountCents });
    amountInput.value = '';
    amountInput.focus();
    updateAll();
  }

  function removeExpense(id) {
    expenses = expenses.filter(exp => exp.id !== id);
    updateAll();
  }

  // Initialize
  form.addEventListener('submit', addExpense);

  // Set initial state
  updateAll();
})();
